        ends[max(p)].append(p)
    col = [0] * (n - 1)
    best = 1
    def dfs(i, count):
        nonlocal best
        if count + n - 1 - i <= best:
            return
        if i == n - 1:
            best = max(best, count)
            return
        for c in range(count + 1):
            col[i] = c
            if any(len({col[j] for j in p}) == k for p in ends[i]):
                continue
            dfs(i + 1, max(count, c + 1))
    col[0] = 0
    dfs(1, 1)
    return best

def d_brute(a, b):
