void solve()
{
	cin >> n >> m;
	int s = 0;
	for (int i = 1; i <= n; ++i)
		for (int j = 1; j <= m; ++j)
		{
			cin >> a[(i - 1) * m + j];
			c[i] += a[(i - 1) * m + j];
			s += a[(i - 1) * m + j];
		}
	if (s % n)
	{
		cout << -1 << endl;
		return;
	}
	int t = s / n, ans = 0;
	for (int i = 1; i <= n; ++i)
		ans += max(0, c[i] - t);
	cout << ans << endl;
	for (int j = 1; j <= m; ++j)
	{
		int x = 0, y = 0;
		for (int i = 1; i <= n; ++i)
			if (c[i] > t && a[(i - 1) * m + j])
