struct node
{
	int x, y, id, t;
} a[M];
struct rect
{
	int x1, y1, x2, y2, l, r, fa;
} b[N];
struct event
{
	int x, t, id;
} e[M];
set<tuple<int, int, int>> s;

void init() {}

bool cmp(node u, node v)
{
	if (u.x != v.x)
		return u.x > v.x;
	if (u.t != v.t)
		return u.t < v.t;
	return u.y > v.y;
}

bool cmp2(event u, event v)
{
	if (u.x != v.x)
		return u.x < v.x;
	if (u.t != v.t)
		return u.t < v.t;
	if (b[u.id].y1 != b[v.id].y1)
		return u.t ? b[u.id].y1 < b[v.id].y1 : b[u.id].y1 > b[v.id].y1;
	return u.t ? b[u.id].y2 > b[v.id].y2 : b[u.id].y2 < b[v.id].y2;
}

void update(int p, int v)
{
	mn[p] = mx[p] = tg[p] = v;
}

void pushdown(int p)
{
	if (tg[p] != -1)
	{
		update(p << 1, tg[p]);
		update(p << 1 | 1, tg[p]);
		tg[p] = -1;
	}
}

void modify(int p, int l, int r, int x, int y, int v)
{
	if (x <= l && r <= y)
	{
		update(p, v);
		return;
	}
	pushdown(p);
	int mid = (l + r) >> 1;
	if (x <= mid)
		modify(p << 1, l, mid, x, y, v);
	if (y > mid)
		modify(p << 1 | 1, mid + 1, r, x, y, v);
	mn[p] = min(mn[p << 1], mn[p << 1 | 1]);
	mx[p] = max(mx[p << 1], mx[p << 1 | 1]);
}

void query(int p, int l, int r, int x, int y)
{
	if ((x <= l && r <= y) || tg[p] != -1)
	{
		ql = min(ql, mn[p]);
		qr = max(qr, mx[p]);
		return;
	}
	int mid = (l + r) >> 1;
	if (x <= mid)
		query(p << 1, l, mid, x, y);
	if (y > mid)
		query(p << 1 | 1, mid + 1, r, x, y);
}

void solve()
{
