			b[u].x2 = x[p];
			b[u].y2 = y[p];
		}
		for (int i = 1; i <= n; ++i)
			for (int j = 1; j < i; ++j)
				if (!check(i, j))
				{
					cout << "No" << endl;
					return;
				}
	}
	cout << "Yes" << endl;
	for (int i = 1; i <= n; ++i)
		cout << ans[i] << endl;
}

int main()
{
#ifndef LOCAL
	freopen("passerby.in", "r", stdin);
	freopen("passerby.out", "w", stdout);
#endif
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	init();
	while (_--)
		solve();
	return 0;
}
